`ifndef XIL_XECLIB
  reg attr_test;
  reg attr_err;
  
  initial begin
  trig_attr = 1'b0;
  `ifdef XIL_ATTR_TEST
    attr_test = 1'b1;
  `else
    attr_test = 1'b0;
  `endif
    attr_err = 1'b0;
    #1;
    trig_attr = ~trig_attr;
  end
`endif

`ifndef XIL_XECLIB
  always @ (trig_attr) begin
    #1;
    if ((attr_test == 1'b1) ||
        ((HNICX_DATA_RATE_REG != "QUIESCENT") &&
         (HNICX_DATA_RATE_REG != "400G"))) begin
      $display("Error: [Unisim %s-101] HNICX_DATA_RATE attribute is set to %s.  Legal values for this attribute are QUIESCENT or 400G. Instance: %m", MODULE_NAME, HNICX_DATA_RATE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((HNICX_DPU_MODE_CRYPTO_OPTIONS_REG != "NO_CRYPTO") &&
         (HNICX_DPU_MODE_CRYPTO_OPTIONS_REG != "CRYPTO") &&
         (HNICX_DPU_MODE_CRYPTO_OPTIONS_REG != "CRYPTO_WITH_CM"))) begin
      $display("Error: [Unisim %s-102] HNICX_DPU_MODE_CRYPTO_OPTIONS attribute is set to %s.  Legal values for this attribute are NO_CRYPTO, CRYPTO or CRYPTO_WITH_CM. Instance: %m", MODULE_NAME, HNICX_DPU_MODE_CRYPTO_OPTIONS_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((HNICX_PACKET_SIZE_REG != 512) &&
         (HNICX_PACKET_SIZE_REG != 1024))) begin
      $display("Error: [Unisim %s-103] HNICX_PACKET_SIZE attribute is set to %d.  Legal values for this attribute are 512 or 1024. Instance: %m", MODULE_NAME, HNICX_PACKET_SIZE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((SIM_AES_EN_REG != "TRUE") &&
         (SIM_AES_EN_REG != "FALSE"))) begin
      $display("Error: [Unisim %s-104] SIM_AES_EN attribute is set to %s.  Legal values for this attribute are TRUE or FALSE. Instance: %m", MODULE_NAME, SIM_AES_EN_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((SIM_CM_EN_REG != "TRUE") &&
         (SIM_CM_EN_REG != "FALSE"))) begin
      $display("Error: [Unisim %s-105] SIM_CM_EN attribute is set to %s.  Legal values for this attribute are TRUE or FALSE. Instance: %m", MODULE_NAME, SIM_CM_EN_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((SIM_VERSION_REG < 1) || (SIM_VERSION_REG > 3))) begin
      $display("Error: [Unisim %s-106] SIM_VERSION attribute is set to %d.  Legal values for this attribute are 1 to 3. Instance: %m", MODULE_NAME, SIM_VERSION_REG);
      attr_err = 1'b1;
    end
    
    if (attr_err == 1'b1) #1 $finish;
  end
`endif


